import { test, expect } from '@playwright/test'
import { sendMessage } from '../conversation'

test.describe('composer', () => {
  test('reports that the agent is working before the first token', async ({ page }) => {
    await page.goto('/')
    await sendMessage(page, 'slow', 'Take your time')

    await expect(page.getByRole('status')).toContainText('Thinking')
    await expect(page.getByText('Taking my time here.')).toBeVisible({ timeout: 15_000 })
  })

  test('offers a stop control while a run is in flight', async ({ page }) => {
    await page.goto('/')
    await sendMessage(page, 'slow', 'Take your time')

    const stop = page.getByRole('button', { name: 'Stop generating' })
    await expect(stop).toBeVisible()
    await stop.click()

    // Back to a sendable composer, with whatever streamed so far left in place.
    await expect(page.getByRole('button', { name: 'Send message' })).toBeVisible()
    await expect(stop).toBeHidden()
  })

  test('send is disabled until there is a message to send', async ({ page }) => {
    await page.goto('/')

    const send = page.getByRole('button', { name: 'Send message' })
    await expect(send).toBeDisabled()

    await page.getByPlaceholder('What would you like to know?').fill('Hello')
    await expect(send).toBeEnabled()
  })
})

import { describe, expect, it } from 'vitest'

import { resolveSelectedModel } from '../../src/lib/models'

const model = (id: string) => ({ id, name: id, builtinTools: [] })

describe('resolveSelectedModel', () => {
  it('selects the first model when nothing is selected yet', () => {
    expect(resolveSelectedModel([model('a'), model('b')], '')).toBe('a')
  })

  it('keeps a selection the backend still advertises', () => {
    // Otherwise every refetch while a conversation is open would silently drag
    // the user back to the first model.
    expect(resolveSelectedModel([model('a'), model('b')], 'b')).toBe('b')
  })

  it('falls back to the first model when the selected one is withdrawn', () => {
    expect(resolveSelectedModel([model('a'), model('c')], 'b')).toBe('a')
  })

  it('clears the selection when the configuration comes back empty', () => {
    // The select is hidden with no models, so a stale id could not be corrected
    // — and it kept the send button enabled, putting a model the backend no
    // longer advertises on the next request.
    expect(resolveSelectedModel([], 'b')).toBe('')
  })
})

import { test, expect } from '@playwright/test'
import { chat, sendMessage } from '../conversation'

const providers = ['anthropic', 'openai', 'google']

for (const model of providers) {
  test.describe(model, () => {
    test('streams a response', async ({ page }) => {
      await page.goto('/')
      await sendMessage(page, model, 'Reply with exactly: hello world')
      await expect(chat(page).getByRole('paragraph').last()).toContainText('hello', {
        timeout: 30_000,
      })
    })
  })
}

import { test, expect } from '@playwright/test'
import { sendMessage } from '../conversation'

test.describe('model selector', () => {
  test('shows available models from server', async ({ page }) => {
    await page.goto('/')
    await page
      .getByRole('combobox')
      .filter({ hasNotText: /^Effort:/ })
      .click()
    await expect(page.getByRole('option', { name: 'text' })).toBeVisible()
    await expect(page.getByRole('option', { name: 'tool', exact: true })).toBeVisible()
    await expect(page.getByRole('option', { name: 'multi-tool' })).toBeVisible()
  })

  test('can select a model and send a message', async ({ page }) => {
    await page.goto('/')
    await sendMessage(page, 'text', 'hello')

    await expect(page.getByText('Hello from the test server')).toBeVisible()
  })
})

